var RULES = {"kb-fake":{"Title":"Looks like a button but is not one","What":"{name} works when clicked with a mouse, but the keyboard cannot reach it and screen readers do not call it a button.","Who":"Keyboard and screen reader users","Fix":"Use a real button, or add button behavior for screen readers and the keyboard.","Wcag":"4.1.2","WcagName":"Name, Role, Value","Dof":"ARIA on custom controls"},"kb-fake-check":{"Title":"Might be clickable but is not a button","What":"{name} shows the hand pointer like something you can click, but it is not a link or button. If it does something when clicked, keyboard users cannot use it.","Who":"Keyboard and screen reader users","Fix":"If it can be clicked, make it a real button. If not, remove the hand pointer.","Wcag":"2.1.1","WcagName":"Keyboard","Dof":"Make interactive elements easy to identify"},"kb-focus-hidden-item":{"Title":"Keyboard lands on something invisible","What":"Pressing Tab moves to {name}, but it cannot be seen on the screen, so users lose track of where they are.","Who":"Keyboard users","Fix":"Hide it from the keyboard too when it is hidden, or show it when it gets focus.","Wcag":"2.4.7","WcagName":"Focus Visible","Dof":"Visible focus outline"},"kb-focus-invisible":{"Title":"Cannot see where the keyboard is","What":"When {name} has keyboard focus, nothing on the screen changes to show it.","Who":"Keyboard users and people with low vision","Fix":"Show a clear outline or highlight on whatever has keyboard focus.","Wcag":"2.4.7","WcagName":"Focus Visible","Dof":"Visible focus outline"},"kb-obscured":{"Title":"Focused item hidden behind a header or banner","What":"When {name} has keyboard focus it is completely covered by {cover}.","Who":"Keyboard users","Fix":"Keep focused items from sliding under sticky headers or footers.","Wcag":"2.4.11","WcagName":"Focus Not Obscured (Minimum)","Dof":""},"kb-order":{"Title":"Tab order jumps around","What":"Pressing Tab jumps {example}. The numbered picture shows the full order.","Who":"Keyboard and screen reader users","Fix":"Make Tab move top left to bottom right, in the same order things appear on screen.","Wcag":"2.4.3","WcagName":"Focus Order","Dof":"Tab order top left to bottom right"},"kb-skip":{"Title":"No way to skip past the menu","What":"Keyboard users have to tab through {count} menu items before reaching the content, on every screen.","Who":"Keyboard and screen reader users","Fix":"Add a Skip to Main Content link at the top and mark the main content area.","Wcag":"2.4.1","WcagName":"Bypass Blocks","Dof":"HTML5 grouping tags"},"kb-trap":{"Title":"Keyboard gets stuck","What":"Once focus reaches {name}, pressing Tab keeps cycling through the same {count} items and Esc does not get out.","Who":"People who cannot use a mouse","Fix":"Let Tab and Esc move focus out of this area.","Wcag":"2.1.2","WcagName":"No Keyboard Trap","Dof":"Exit popups with Esc or Tab"},"kb-unreachable":{"Title":"Cannot be reached with the keyboard","What":"{name} can be clicked with a mouse, but pressing Tab never moves to it.","Who":"People who cannot use a mouse","Fix":"Make it a real button or link, or allow it to take keyboard focus.","Wcag":"2.1.1","WcagName":"Keyboard","Dof":"Keyboard only operation"},"spacing-clip":{"Title":"Text cut off with wider spacing","What":"When line and letter spacing are increased, the text \"{text}\" is {how}.","Who":"People with dyslexia or low vision who use custom spacing","Fix":"Avoid fixed heights and widths on boxes that hold text.","Wcag":"1.4.12","WcagName":"Text Spacing","Dof":""},"spacing-overlap":{"Title":"Text overlaps with wider spacing","What":"When line and letter spacing are increased, the text \"{text}\" runs into \"{other}\".","Who":"People with dyslexia or low vision who use custom spacing","Fix":"Avoid fixed heights and positions on boxes that hold text.","Wcag":"1.4.12","WcagName":"Text Spacing","Dof":""},"sr-dup-title":{"Title":"Several screens share one title","What":"{count} screens all have the title \"{title}\", so users cannot tell them apart.","Who":"Screen reader users switching between tabs","Fix":"Give each screen its own title.","Wcag":"2.4.2","WcagName":"Page Titled","Dof":""},"sr-fake-heading":{"Title":"Looks like a heading but is not coded as one","What":"{text} look like section titles, but screen readers treat them as plain text, so users cannot jump between sections.","Who":"Screen reader users","Fix":"Code section titles as headings.","Wcag":"1.3.1","WcagName":"Info and Relationships","Dof":"Section header text"},"sr-heading-skip":{"Title":"Heading levels skip","What":"Headings jump from level {from} to level {to} at \"{text}\", which makes the page outline confusing.","Who":"Screen reader users","Fix":"Use heading levels in order without skipping.","Wcag":"1.3.1","WcagName":"Info and Relationships","Dof":"Semantic markup"},"sr-hidden-focusable":{"Title":"Hidden from screen readers but still reachable","What":"Keyboard focus can land on {name}, but it is hidden from screen readers, so they hear nothing.","Who":"Screen reader users","Fix":"Either show it to screen readers or remove it from the keyboard order.","Wcag":"4.1.2","WcagName":"Name, Role, Value","Dof":"Screen reader reads content"},"sr-img-badalt":{"Title":"Image description is not helpful","What":"This image is described only as \"{alt}\", which does not say what it shows.","Who":"Blind users","Fix":"Describe what the image shows or why it is there.","Wcag":"1.1.1","WcagName":"Non-text Content","Dof":"Alternative text for images"},"sr-img-noalt":{"Title":"Image has no description","What":"This image has no description, so a screen reader either skips it or reads out a file name.","Who":"Blind users","Fix":"Add a short description, or mark it as decorative if it adds nothing.","Wcag":"1.1.1","WcagName":"Non-text Content","Dof":"Alternative text for images"},"sr-label-in-name":{"Title":"Spoken name does not match the words on screen","What":"The button shows \"{visible}\" but screen readers and voice control know it as \"{spoken}\".","Who":"Voice control users who say what they see","Fix":"Make the spoken name start with the same words shown on screen.","Wcag":"2.5.3","WcagName":"Label in Name","Dof":"Consistent button and link labels"},"sr-landmarks":{"Title":"Page areas not marked","What":"The screen has no {regions} area marked for screen readers, so users cannot jump to it.","Who":"Screen reader users","Fix":"Mark the header, menu, main content and footer areas.","Wcag":"1.3.1","WcagName":"Info and Relationships","Dof":"HTML5 grouping tags"},"sr-no-h1":{"Title":"No main heading","What":"The screen has no main heading, so screen reader users cannot jump straight to the start of the content.","Who":"Screen reader users","Fix":"Add one main heading that names the screen.","Wcag":"1.3.1","WcagName":"Info and Relationships","Dof":"Semantic markup"},"sr-no-label":{"Title":"Field has no label","What":"A screen reader reads this field with no label, so users do not know what to type.","Who":"Screen reader users","Fix":"Tie the visible label to the field.","Wcag":"1.3.1","WcagName":"Info and Relationships","Dof":"Fields labeled and announced"},"sr-no-lang":{"Title":"Page language not set","What":"The page does not say it is in English, so screen readers may pronounce words wrong.","Who":"Screen reader users","Fix":"Set the page language to English.","Wcag":"3.1.1","WcagName":"Language of Page","Dof":""},"sr-no-title":{"Title":"Screen has no title","What":"This screen has no title, so the browser tab and screen readers have nothing to announce.","Who":"Screen reader users switching between tabs","Fix":"Give each screen its own title.","Wcag":"2.4.2","WcagName":"Page Titled","Dof":""},"sr-placeholder":{"Title":"Field label disappears when typing","What":"The field \"{name}\" only has gray hint text inside it. The hint vanishes once someone starts typing.","Who":"People with memory or attention difficulties, and screen reader users","Fix":"Add a visible label above or beside the field.","Wcag":"3.3.2","WcagName":"Labels or Instructions","Dof":"Label and input pairs"},"sr-reading-order":{"Title":"Reading order does not match the screen","What":"The screen reader reads \"{a}\" before \"{b}\", but \"{b}\" appears above it on screen.","Who":"Screen reader users","Fix":"Arrange the page so the reading order matches what people see.","Wcag":"1.3.2","WcagName":"Meaningful Sequence","Dof":"Logical reading order"},"sr-required":{"Title":"Required field not announced","What":"The field \"{name}\" is marked required on screen, but the screen reader does not say it is required.","Who":"Screen reader users","Fix":"Mark the field as required so it is announced.","Wcag":"3.3.2","WcagName":"Labels or Instructions","Dof":"Fields labeled and announced"},"sr-table-headers":{"Title":"Table has no column headings","What":"The table {table} has no column headings tied to its cells, so a screen reader reads numbers with no context.","Who":"Screen reader users","Fix":"Give every column a heading cell.","Wcag":"1.3.1","WcagName":"Info and Relationships","Dof":"Table headings"},"sr-unnamed":{"Title":"Control has no name","What":"The screen reader only says \"{role}\" for this item, with no name, so users cannot tell what it does.","Who":"Screen reader and voice control users","Fix":"Give it a name that says what it does. The name can be hidden from sight and still be read aloud.","Wcag":"4.1.2","WcagName":"Name, Role, Value","Dof":"Screen reader reads labels and buttons"},"sr-vague":{"Title":"Links all say the same thing","What":"{count} links or buttons all say \"{name}\" but go to different places.","Who":"Screen reader users who browse a list of links","Fix":"Make each one say where it goes, like View Budget Details.","Wcag":"2.4.4","WcagName":"Link Purpose (In Context)","Dof":"Meaningful link and button text"},"tool-error":{"Title":"Part of the test could not run","What":"The {module} test could not finish on this screen. {detail}","Who":"Nobody, this is a note about the tool","Fix":"Run the test on this screen again. If it keeps happening, send the Run Log to whoever maintains the tool.","Wcag":"","WcagName":"","Dof":""},"vis-sensory":{"Title":"Instructions rely on color or position","What":"The screen says \"{quote}\", which only works if you can see the color, shape or position.","Who":"Blind and color blind users","Fix":"Refer to things by their name, like click the Save button.","Wcag":"1.3.3","WcagName":"Sensory Characteristics","Dof":"Avoid relying on color alone"},"vis-target-size":{"Title":"Click targets too small","What":"{count} clickable items are smaller than 24 by 24 pixels and packed close together. For example {name} is {w} by {h} pixels.","Who":"People with tremors or limited hand control","Fix":"Make them bigger or add space around them.","Wcag":"2.5.8","WcagName":"Target Size (Minimum)","Dof":""},"zoom-clip-200":{"Title":"Text cut off at 200% zoom","What":"At 200% zoom the text \"{text}\" is {how}, so part of it cannot be read.","Who":"People with low vision who zoom in","Fix":"Let the box grow with its text instead of using a fixed size.","Wcag":"1.4.4","WcagName":"Resize Text","Dof":"Zoom 200% layout intact"},"zoom-clip-400":{"Title":"Text cut off at 400% zoom","What":"At 400% zoom the text \"{text}\" is {how}, so part of it cannot be read.","Who":"People with low vision who zoom in","Fix":"Let the box grow with its text instead of using a fixed size.","Wcag":"1.4.10","WcagName":"Reflow","Dof":"No side scroll on small screens"},"zoom-lost":{"Title":"Content disappears at 400% zoom","What":"The text \"{text}\" shows at normal size but is hidden or off screen at 400% zoom.","Who":"People with low vision who zoom in","Fix":"Keep it on screen at narrow widths, or move it into a menu that can still be opened.","Wcag":"1.4.10","WcagName":"Reflow","Dof":"No side scroll on small screens"},"zoom-overlap-200":{"Title":"Text overlaps at 200% zoom","What":"At 200% zoom the text \"{text}\" sits on top of \"{other}\".","Who":"People with low vision who zoom in","Fix":"Give items room to move when the text gets bigger.","Wcag":"1.4.4","WcagName":"Resize Text","Dof":"Zoom 200% layout intact"},"zoom-overlap-400":{"Title":"Text overlaps at 400% zoom","What":"At 400% zoom the text \"{text}\" sits on top of \"{other}\", so neither can be read clearly.","Who":"People with low vision who zoom in","Fix":"Give items room to move and stack when the screen gets narrow.","Wcag":"1.4.10","WcagName":"Reflow","Dof":"No side scroll on small screens"},"zoom-reflow":{"Title":"Sideways scrolling at 400% zoom","What":"At 400% zoom you have to scroll sideways to read this screen. The page is {width} pixels wide instead of fitting the window. The widest items are {items}.","Who":"People with low vision who zoom in","Fix":"Let the layout stack into one column on narrow screens instead of using a fixed width.","Wcag":"1.4.10","WcagName":"Reflow","Dof":"No side scroll on small screens"},"zoom-reflow-table":{"Title":"Table or grid scrolls sideways at 400% zoom","What":"At 400% zoom the screen scrolls sideways because of {items}. WCAG allows this for data tables and maps, so please confirm the rest of the screen still fits.","Who":"People with low vision who zoom in","Fix":"If only the table scrolls, put it in its own scrolling box so the rest of the page fits the window.","Wcag":"1.4.10","WcagName":"Reflow","Dof":"No side scroll on small screens"}};
